mapper.select:
SELECT tc.id, tc.course_id, tc.course, tc.teacher_no, tc.course_credit, tc.capacity, ct.weekday, ct.start_section, ct.end_section,
CONVERT(VARCHAR, ISNULL(cct.course_type, tc.course_type)) IFNULL(cct.course_type, tc.course_type) as course_type,
ISNULL(sc_count.num, 0) IFNULL(sc_count.num, 0) as selected_count, ct.location FROM teacher_course tc JOIN class_time ct ON tc.course_id = ct.course_id JOIN student_info s ON s.student_no = #{studentNo} LEFT JOIN class_course_type cct ON tc.course_id = cct.course_id AND cct.class_id = s.class_name AND cct.year = s.year LEFT JOIN ( SELECT course_id, count(*) as num FROM student_course_selection GROUP BY course_id ) sc_count ON tc.course_id = sc_count.course_id WHERE 1=1
AND tc.course = #{subject}
AND ISNULL(cct.course_type, tc.course_type) IFNULL(cct.course_type, tc.course_type) = #{courseType}
